mapper.select:
SELECT T.CONTENT_ID, T.CONTENT_TYPE_ID, T.CATEGORY_ID, C.NAME AS CATEGORY_NAME, T.TITLE, T.FIRST_IMAGE, T.ADDR1, T.ADDR2, T.MAP_X, T.MAP_Y, T.VIEW_COUNT, T.CREATED_TIME, L.L_DONG_SIGNGU_NM AS REGION_NAME, COUNT(DISTINCT F.FAVORITE_ID) AS FAVORITE_COUNT, COUNT(DISTINCT R.REVIEW_ID) AS REVIEW_COUNT, FI.EVENT_START_DATE, FI.EVENT_END_DATE, CASE WHEN SUM(CASE WHEN F2.USER_ID = #{userId} THEN 1 ELSE 0 END) > 0 THEN 'Y' ELSE 'N' END AS LIKED_YN FROM TOUR_PLACE T LEFT JOIN LDONG L ON T.L_DONG_SIGNGU_CD = L.L_DONG_SIGNGU_CD LEFT JOIN CATEGORY C ON T.CATEGORY_ID = C.ID LEFT JOIN FAVORITE F ON T.CONTENT_ID = F.CONTENT_ID LEFT JOIN REVIEW R ON T.CONTENT_ID = R.CONTENT_ID AND R.REVIEW_ACTIVE = 'Y' LEFT JOIN FAVORITE F2 ON T.CONTENT_ID = F2.CONTENT_ID AND F2.USER_ID = #{userId} LEFT JOIN FESTIVAL_INTRO FI ON T.CONTENT_ID = FI.CONTENT_ID
AND (T.TITLE LIKE CONCAT('%', #{keyword}, '%') OR T.ADDR1 LIKE CONCAT('%', #{keyword}, '%'))
AND T.CATEGORY_ID = #{categoryId}
AND T.L_DONG_SIGNGU_CD IN (
110, 111, 113
#{regionCd}
)
AND FI.EVENT_START_DATE <= CURDATE() AND FI.EVENT_END_DATE >= CURDATE()
AND FI.EVENT_START_DATE > CURDATE()
GROUP BY T.CONTENT_ID, T.CONTENT_TYPE_ID, T.CATEGORY_ID, C.NAME, T.TITLE, T.FIRST_IMAGE, T.ADDR1, T.ADDR2, T.MAP_X, T.MAP_Y, T.VIEW_COUNT, T.CREATED_TIME, L.L_DONG_SIGNGU_NM
ORDER BY FAVORITE_COUNT DESC
ORDER BY T.CREATED_TIME DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM TOUR_PLACE T LEFT JOIN FESTIVAL_INTRO FI ON T.CONTENT_ID = FI.CONTENT_ID
AND (T.TITLE LIKE CONCAT('%', #{keyword}, '%') OR T.ADDR1 LIKE CONCAT('%', #{keyword}, '%'))
AND T.CATEGORY_ID = #{categoryId}
AND T.L_DONG_SIGNGU_CD IN (
110, 111, 113
#{regionCd}
)
AND FI.EVENT_START_DATE <= CURDATE() AND FI.EVENT_END_DATE >= CURDATE()
AND FI.EVENT_START_DATE > CURDATE()

mapper.update:
UPDATE TOUR_PLACE
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE CONTENT_ID = #{contentId}

mapper.select:
SELECT COUNT(*)
FROM FAVORITE
WHERE CONTENT_ID = #{contentId}
  AND USER_ID    = #{userId}

mapper.delete:
DELETE FROM FAVORITE
WHERE CONTENT_ID = #{contentId}
  AND USER_ID    = #{userId}
